.appearance-options>button:hover{border-color:var(--ui-border)}
.appearance-options>button.on{border-color:var(--ui-primary);background:var(--ui-primary-soft)}
.appearance-options b{font-size:13px;font-weight:650}
.swatch{width:100%;aspect-ratio:16/9;border-radius:10px;display:flex;gap:6px;padding:8px;overflow:hidden;border:1px solid rgba(128,128,128,.25)}
