.swatch-light{--sw-side:#fff;--sw-card:#fff;background:#f6f6f7}.swatch-dark{--sw-side:#1e1e21;--sw-card:#1e1e21;background:#0f0f10}
.swatch-system{--sw-side:#fff;--sw-card:#1e1e21;background:linear-gradient(90deg,#f6f6f7 50%,#0f0f10 50%)}
.settings-content{max-width:840px;display:grid;gap:var(--ui-section-gap);margin-top:18px}.settings-content>.surface{padding:25px}.settings-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}.source-errors{margin-top:16px}.data-location{display:flex;gap:var(--ui-section-gap);align-items:center}.data-location code{flex:1;overflow-wrap:anywhere;font-size:12px;background:var(--ui-surface-alt);border:1px solid var(--ui-line);border-radius:8px;padding:12px}.about-identity{display:flex;align-items:center;gap:var(--ui-section-gap)}.about-logo{width:85px;height:85px;display:grid;place-items:center;background:var(--ui-primary-soft);border-radius:20px}.about-logo img{width:64px;height:64px}.about-identity h2{font-size:22px;margin:0 0 6px}.about-identity p{color:var(--ui-muted);margin:0 0 13px}.about-identity .n-tag{margin-right:8px}.release-details{background:var(--ui-surface-alt);border-radius:10px;padding:18px}.release-details p{white-space:pre-wrap;line-height:1.8}.about-note{display:flex;gap:7px;align-items:center;font-size:12px;margin:12px 0 0}.announcement{padding:16px 0;border-top:1px solid var(--ui-line)}.announcement>div{display:flex;justify-content:space-between;align-items:center}.announcement h3{font-size:14px;margin:0}.announcement p{white-space:pre-wrap;line-height:1.8;color:var(--ui-muted);font-size:14px}@media(max-width:760px){.data-location{flex-direction:column;align-items:stretch}}
</style>
